// Sample input for a clearly-fictional, disclosed synthetic character.
return [{ json: {
  character_name: 'Nova Vale (fictional)',
  niche: 'indie sci-fi book recommendations',
  disclosure: true,
  voice_consent: false,
  backstory: 'A fictional archivist character created for a book-review channel.',
  personality: ['curious', 'dry humor', 'warm'],
  topics_avoided: ['real politics', 'medical advice'],
  physical_descriptors: ['teal eyes', 'silver undercut', 'freckles', 'angular jaw'],
  output_dir: './synthetic-character'
} }];

const j = $input.first().json;
const e = [];
if (typeof j.character_name !== 'string' || !j.character_name.trim()) e.push('character_name required');
if (j.disclosure !== true) e.push('disclosure must be true: synthetic characters must be labelled as AI');
if (!Array.isArray(j.physical_descriptors) || j.physical_descriptors.length < 6 || j.physical_descriptors.length > 8) e.push('physical_descriptors must lock 6-8 traits (per source)');
if (e.length) throw new Error('Blocked: ' + e.join('; '));
return [{ json: j }];

const j = $input.first().json;
const dir = (j.output_dir || './synthetic-character').replace(/\/+$/, '');
const disc = '> SYNTHETIC / AI-GENERATED CHARACTER. Not a real person. Must be disclosed on every platform.';
const persona = ['# persona.md', '', disc, '', '## Name', j.character_name, '', '## Niche', j.niche || '', '', '## Backstory', j.backstory || '(write full backstory)', '', '## Personality', (j.personality||[]).map(x=>'- '+x).join('\n')||'- (add traits)', '', '## Topics never discussed', (j.topics_avoided||[]).map(x=>'- '+x).join('\n')||'- (add)', '', '## Done when', 'You can answer 20 questions about this character without thinking.'].join('\n');
const voice = ['# voice.md', '', disc, '', '## Consent gate', 'voice_consent = ' + (j.voice_consent === true), '', j.voice_consent === true ? 'Proceed with a LICENSED/CONSENTED voice sample only.' : 'BLOCKED: no cloning until you have a licensed/consented voice sample.', '', '## MANUAL HANDOFF', '- Obtain a consented voice sample.', '- Clone via a provider you are authorised to use.', '- Document cadence, filler words, how she sounds on voice notes.'].join('\n');
const flux = ['# flux.md', '', disc, '', '## Locked physical descriptors (6-8)', (j.physical_descriptors||[]).map(x=>'- '+x).join('\n'), '', '## MANUAL HANDOFF', '- Pick one base face (not a real identifiable person).', '- Generate ~50 variations, fine-tune a LoRA on rented GPU.', '- Define 3 lighting setups for variety without changing the face.'].join('\n');
const brain = ['# brain.md', '', disc, '', '## Memory store', 'Append-only log of brand/follower/conversation context so the character stays consistent.', '', '## Schema', '- date', '- entity (brand/follower)', '- summary', '- engaged_content', '', '## MANUAL HANDOFF', 'Wire a scheduled job to read all four files before each interaction. Keep a human in the loop for outreach.'].join('\n');
return [
  { json: { fileName: dir + '/persona.md', content: persona } },
  { json: { fileName: dir + '/voice.md', content: voice } },
  { json: { fileName: dir + '/flux.md', content: flux } },
  { json: { fileName: dir + '/brain.md', content: brain } }
];

const sourceId="DZThO_qvCK7";
const sourceUrl="https://www.instagram.com/raycfu/reel/DZThO_qvCK7/";
const variant='USER_STACK';
const seen=new Set();
const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16).padStart(8,'0');};
return $input.all().map(({json:j},i)=>{
  const recordKey=String(j.row_id||j.clip_id||j.note_id||j.fileName||j.output_path||j.title||i);
  const idempotencyKey=hash(sourceId+'|'+recordKey);
  if(seen.has(idempotencyKey)) throw new Error('Duplicate output in one execution: '+idempotencyKey);
  seen.add(idempotencyKey);
  return {json:{...j,source_provenance:{source_id:sourceId,source_url:sourceUrl,variant},idempotency_key:idempotencyKey,review_status:'needs_human_review',review_notes:Array.isArray(j.review_notes)?j.review_notes:[],external_actions_enabled:false}};
});
